begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select plan(38);
insert into auth.users(id,email) values('92900000-0000-4000-8000-000000000001','teacher@release.test'),('92900000-0000-4000-8000-000000000002','learner-a@release.test'),('92900000-0000-4000-8000-000000000003','learner-b@release.test');
insert into public.user_roles(user_id,role) values('92900000-0000-4000-8000-000000000001','teacher');
set local request.jwt.claim.sub='92900000-0000-4000-8000-000000000001';
insert into public.courses(id,slug,title,position,status,owner_user_id) values(929001,'release-test','Release Test',929001,'draft','92900000-0000-4000-8000-000000000001');
insert into public.units(id,course_id,title,position,status) values(929011,929001,'Unit A',0,'draft');
insert into public.lessons(id,unit_id,title,position,status) values(929021,929011,'Lesson A',0,'draft');
insert into public.lesson_versions(id,lesson_id,version_number,status,created_by) values(929031,929021,1,'draft','92900000-0000-4000-8000-000000000001');
insert into public.lesson_activities(id,lesson_version_id,type,title,position) values(929041,929031,'theory','V1 Activity',0);
insert into public.theory_blocks(id,activity_id,block_type,position,text) values(929051,929041,'paragraph',0,'V1');
set local role authenticated;
select is((public.publish_course(929001)->>'ok')::boolean,true,'publishing state A succeeds');
set constraints capture_course_release_after_publication immediate;
reset role;
select is((select count(*)::integer from public.course_releases where course_id=929001),1,'Release 1 created');
select is((select lesson_version_id from public.course_release_lessons l join public.course_release_units u on u.id=l.course_release_unit_id where u.course_release_id=(select id from public.course_releases where course_id=929001)),929031::bigint,'Release 1 pins Version 1');
select is((select count(*)::integer from public.course_release_units where course_release_id=(select id from public.course_releases where course_id=929001)),1,'draft Unit excluded');
set local role authenticated; set local request.jwt.claim.sub='92900000-0000-4000-8000-000000000001';
select is((public.publish_course(929001)->>'ok')::boolean,true,'unchanged republish succeeds');
set constraints capture_course_release_after_publication immediate;
reset role;
select is((select count(*)::integer from public.course_releases where course_id=929001),1,'unchanged republish is idempotent');
insert into public.units(id,course_id,title,position,status) values(929012,929001,'Future Unit',1,'draft');
insert into public.lessons(id,unit_id,title,position,status) values(929022,929012,'New Lesson',0,'draft');
insert into public.lesson_versions(id,lesson_id,version_number,status,created_by) values(929032,929022,1,'draft','92900000-0000-4000-8000-000000000001');
insert into public.lesson_activities(id,lesson_version_id,type,title,position) values(929042,929032,'theory','New Activity',0);
insert into public.theory_blocks(id,activity_id,block_type,position,text) values(929052,929042,'paragraph',0,'New');
insert into public.lessons(id,unit_id,title,position,status) values(929023,929011,'Lesson B',1,'draft'),(929024,929011,'Lesson C',2,'draft');
insert into public.lesson_versions(id,lesson_id,version_number,status,created_by) values(929034,929023,1,'draft','92900000-0000-4000-8000-000000000001'),(929035,929024,1,'draft','92900000-0000-4000-8000-000000000001');
insert into public.lesson_activities(id,lesson_version_id,type,title,position) values(929044,929034,'theory','B Activity',0),(929045,929035,'theory','C Activity',0);
insert into public.theory_blocks(id,activity_id,block_type,position,text) values(929054,929044,'paragraph',0,'B'),(929055,929045,'paragraph',0,'C');
insert into public.lesson_versions(id,lesson_id,version_number,status,created_by) values(929033,929021,2,'draft','92900000-0000-4000-8000-000000000001');
insert into public.lesson_activities(id,lesson_version_id,type,title,position) values(929043,929033,'theory','V2 Activity',0);
insert into public.theory_blocks(id,activity_id,block_type,position,text) values(929053,929043,'paragraph',0,'V2');
set local role authenticated; set local request.jwt.claim.sub='92900000-0000-4000-8000-000000000001';
select is((public.publish_course(929001)->>'ok')::boolean,true,'publishing state B succeeds');
set constraints capture_course_release_after_publication immediate;
reset role;
select is((select count(*)::integer from public.course_releases where course_id=929001),2,'Release 2 created');
select is((select lesson_version_id from public.course_release_lessons l join public.course_release_units u on u.id=l.course_release_unit_id join public.course_releases r on r.id=u.course_release_id where r.course_id=929001 and r.release_number=1),929031::bigint,'Release 1 remains Version 1');
select is((select lesson_version_id from public.course_release_lessons l join public.course_release_units u on u.id=l.course_release_unit_id join public.course_releases r on r.id=u.course_release_id where r.course_id=929001 and r.release_number=2 and l.source_lesson_id=929021),929033::bigint,'Release 2 pins Version 2');
select throws_ok($$update public.course_releases set course_title='Mutated' where course_id=929001 and release_number=1$$,'Course Release manifests are immutable','Release header immutable');
select throws_ok($$update public.course_release_lessons set title='Mutated' where source_lesson_id=929021$$,'Course Release manifests are immutable','Release Lesson immutable');
insert into public.course_release_learner_entitlements(course_release_id,learner_id) select id,'92900000-0000-4000-8000-000000000002' from public.course_releases where course_id=929001;
create temporary table release_test_ids as select r.release_number,r.id release_id,l.id release_lesson_id,l.source_lesson_id from public.course_releases r join public.course_release_units u on u.course_release_id=r.id join public.course_release_lessons l on l.course_release_unit_id=u.id where r.course_id=929001;
grant select on release_test_ids to authenticated;
grant execute on function public.release_lesson_is_eligible(uuid,bigint) to authenticated;
set local role authenticated; set local request.jwt.claim.sub='92900000-0000-4000-8000-000000000002';
select is((public.get_course_release_lesson((select release_lesson_id from release_test_ids where release_number=1 and source_lesson_id=929021),1)#>>'{lesson,currentVersionId}')::bigint,929031::bigint,'Release 1 delivers V1 after V2 current');
select is((public.get_course_release_lesson((select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929021),1)#>>'{lesson,currentVersionId}')::bigint,929033::bigint,'Release 2 delivers V2');
select ok(public.release_lesson_is_eligible('92900000-0000-4000-8000-000000000002',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929021)),'first Lesson is eligible with zero Release progress');
select ok(not public.release_lesson_is_eligible('92900000-0000-4000-8000-000000000002',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929023)),'second Lesson initially locked');
select ok(not public.release_lesson_is_eligible('92900000-0000-4000-8000-000000000002',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929024)),'third Lesson initially locked');
select ok(not public.release_lesson_is_eligible('92900000-0000-4000-8000-000000000002',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929022)),'Unit 2 initially locked');
select is(public.get_course_release_lesson((select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929023),1)->>'locked','true','locked direct delivery returns controlled state');
select ok((public.get_course_release_lesson((select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929023),1)->'lesson')='null'::jsonb,'locked delivery exposes no activity payload');
select throws_ok(format('select public.record_release_activity_completion(%s,929044)',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929023)),'PLR03','Complete the previous Release content first','direct completion bypass rejected');
select ok((public.get_my_course_release_progress((select distinct release_id from release_test_ids where release_number=2))#>>'{lessons,0,completedAt}') is null,'Release 2 V2 starts incomplete');
select lives_ok(format('select public.record_release_activity_completion(%s,929043)',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929021)),'first Release 2 Lesson completes');
select ok(public.release_lesson_is_eligible('92900000-0000-4000-8000-000000000002',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929023)),'second Lesson unlocks');
select ok(not public.release_lesson_is_eligible('92900000-0000-4000-8000-000000000002',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929024)),'third Lesson remains locked');
select ok(not public.release_lesson_is_eligible('92900000-0000-4000-8000-000000000002',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929022)),'Unit 2 remains locked');
select lives_ok(format('select public.record_release_activity_completion(%s,929044)',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929023)),'second Lesson completes');
select lives_ok(format('select public.record_release_activity_completion(%s,929045)',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929024)),'third Lesson completes');
select ok(public.release_lesson_is_eligible('92900000-0000-4000-8000-000000000002',(select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929022)),'Unit 2 first Lesson unlocks after Unit 1');
select ok((public.get_course_release_lesson((select release_lesson_id from release_test_ids where release_number=2 and source_lesson_id=929021),1)->'lesson') is not null,'completed Lesson remains reviewable');
select lives_ok($$select public.record_release_activity_completion((select release_lesson_id from release_test_ids where release_number=1 and source_lesson_id=929021),929041)$$,'learner completes V1 in Release 1');
select lives_ok($$select public.record_release_activity_completion((select release_lesson_id from release_test_ids where release_number=1 and source_lesson_id=929021),929041)$$,'duplicate completion idempotent');
select is((select count(*)::integer from public.learner_release_activity_progress where course_release_lesson_id=(select release_lesson_id from release_test_ids where release_number=1 and source_lesson_id=929021) and activity_id=929041),1,'duplicate creates one activity row');
select is((select count(*)::integer from public.learner_lesson_progress),0,'Release progress does not reinterpret public progress');
set local request.jwt.claim.sub='92900000-0000-4000-8000-000000000003';
select throws_ok($$select public.get_course_release_manifest((select distinct release_id from release_test_ids where release_number=1))$$,'Course Release is unavailable','unentitled learner denied');
set local request.jwt.claim.sub='92900000-0000-4000-8000-000000000001';
select throws_ok($$select public.record_release_activity_completion(1,929041)$$,'Learner authentication is required','staff cannot write Release progress');
reset role; set local request.jwt.claim.sub=''; set local role anon;
select throws_ok($$select public.get_my_course_release_progress(1)$$,'permission denied for function get_my_course_release_progress','anonymous denied private progress');
reset role;
select is((select array_agg(release_number order by release_number) from public.course_releases where course_id=929001),array[1,2],'release numbering stable and monotonic');
select * from finish(); rollback;
